def help_answer(question, ctx):
    q = question.lower().replace('ё', 'е')
    if re.search(r'где я|какой (?:клиент|контекст|режим|экран) (?:сейчас|открыт)|что (?:я )?сейчас (?:смотрю|открыто)', q):
        client = ctx.get('client', {})
        return f"Открыт клиент «{client.get('name', 'неизвестно')}», режим «{ {'client':'Клиент','deal':'Сделка','person':'Человек'}.get(ctx.get('scope'), ctx.get('scope')) }», версия {client.get('version', 'не указана')}."
    # Product help is separate from business questions such as 'кто отвечает за закупки'.
    if any(p.get('name', '').split()[-1].lower() in q for p in ctx.get('people', []) if p.get('name')) and not re.search(r'кнопк|нажать|редакт|правк|интерфейс', q):
        return None
    navigation = re.search(r'как |куда |где |почему |зачем |что (?:делает|значит|означает|умеешь)|можешь|умеешь|помощ|инструкц', q)
    if not navigation:
        return None
    if 'mcp' in q or 'мсп' in q:
        return next(text for key, _, text in ARTICLES if key == 'mcp')
    scored = [(sum(term in q for term in terms), text) for _, terms, text in ARTICLES]
    score, answer = max(scored, key=lambda item: item[0])
    return answer if score else None


def help_facts():
    return ['Справка сайта: ' + text for _, _, text in ARTICLES]
